package com.geometryworkshop.wxgc3;

import org.json.JSONArray;
import org.json.JSONObject;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.regex.*;

/** 与src/core/mods.js共用契约。原生只验证/保存源码与媒体，不执行Mod脚本。 */
final class ModCodec {
    static final int MAX_PACKAGE=4*1024*1024,MAX_STATE=64*1024,MAX_SCRIPT=128*1024,MAX_ASSET=512*1024,MAX_MODS=16;
    private final SaveCodec codec;
    ModCodec(SaveCodec codec){this.codec=codec;}
    static int bytes(String v){return v.getBytes(StandardCharsets.UTF_8).length;}
    static JSONObject object(Object raw){Fault.require(raw instanceof JSONObject,"INVALID_MOD");return (JSONObject)raw;}
    static JSONArray list(Object raw,int max){if(raw==null||raw==JSONObject.NULL)return new JSONArray();Fault.require(raw instanceof JSONArray&&((JSONArray)raw).length()<=max,"INVALID_MOD");return (JSONArray)raw;}
    static String text(Object raw,int max,boolean empty){Fault.require(raw instanceof String,"INVALID_MOD");String s=(String)raw;Fault.require(s.codePointCount(0,s.length())<=max&&!s.matches("(?s).*"+SaveCodec.CONTROLS+".*")&&(empty||!s.replaceAll(SaveCodec.WS," ").trim().isEmpty()),"INVALID_MOD");return s.replaceAll("^"+SaveCodec.WS+"|"+SaveCodec.WS+"$","");}
    static String id(Object raw){Fault.require(raw instanceof String&&((String)raw).matches("[a-z0-9][a-z0-9._-]{0,47}"),"INVALID_MOD");return (String)raw;}
    static Object or(Object raw,Object fallback){return raw==null||raw==JSONObject.NULL?fallback:raw;}
    static String color(Object raw,String fallback){Object value=or(raw,fallback);Fault.require(value instanceof String&&((String)value).matches("#[0-9a-fA-F]{6}([0-9a-fA-F]{2})?"),"INVALID_MOD");return (String)value;}
    static long u32(byte[] b,int p){Fault.require(p+4<=b.length,"INVALID_MOD_ASSET");return ((long)(b[p]&255)<<24)|((long)(b[p+1]&255)<<16)|((long)(b[p+2]&255)<<8)|(b[p+3]&255);}
    static int u16(byte[] b,int p,boolean little){Fault.require(p+2<=b.length,"INVALID_MOD_ASSET");return little?((b[p]&255)|((b[p+1]&255)<<8)):(((b[p]&255)<<8)|(b[p+1]&255));}
    static String ascii(byte[] b,int p,int count){if(p<0||p+count>b.length)return "";return new String(b,p,count,StandardCharsets.US_ASCII);}
    static String asset(Object raw){
        try{
            Fault.require(raw instanceof String,"INVALID_MOD_ASSET");String value=(String)raw;Matcher matcher=Pattern.compile("^data:(image/(?:png|jpeg|webp)|audio/(?:wav|mpeg|ogg));base64,([A-Za-z0-9+/]+={0,2})$").matcher(value);Fault.require(matcher.matches(),"INVALID_MOD_ASSET");String type=matcher.group(1),encoded=matcher.group(2);Fault.require(encoded.length()%4==0&&encoded.length()<=((MAX_ASSET+2)/3)*4,"INVALID_MOD_ASSET");byte[] b=Base64.getDecoder().decode(encoded);Fault.require(b.length>0&&b.length<=MAX_ASSET,"INVALID_MOD_ASSET");long width=0,height=0;
            if(type.equals("image/png")){Fault.require(b.length>=24&&(b[0]&255)==137&&ascii(b,1,3).equals("PNG")&&ascii(b,12,4).equals("IHDR"),"INVALID_MOD_ASSET");width=u32(b,16);height=u32(b,20);}
            else if(type.equals("image/jpeg")){
                Fault.require(b.length>=2&&(b[0]&255)==255&&(b[1]&255)==216,"INVALID_MOD_ASSET");int p=2;while(p+4<=b.length){Fault.require((b[p++]&255)==255,"INVALID_MOD_ASSET");while(p<b.length&&(b[p]&255)==255)p++;Fault.require(p<b.length,"INVALID_MOD_ASSET");int marker=b[p++]&255;if(marker==217||marker==218)break;int len=u16(b,p,false);Fault.require(len>=2&&p+len<=b.length,"INVALID_MOD_ASSET");if(Arrays.asList(192,193,194,195,197,198,199,201,202,203,205,206,207).contains(marker)){Fault.require(len>=7,"INVALID_MOD_ASSET");height=u16(b,p+3,false);width=u16(b,p+5,false);break;}p+=len;}
            }else if(type.equals("image/webp")){
                Fault.require(b.length>=30&&ascii(b,0,4).equals("RIFF")&&ascii(b,8,4).equals("WEBP"),"INVALID_MOD_ASSET");String kind=ascii(b,12,4);
                if(kind.equals("VP8X")){width=1+(b[24]&255)+((b[25]&255)<<8)+((b[26]&255)<<16);height=1+(b[27]&255)+((b[28]&255)<<8)+((b[29]&255)<<16);}
                else if(kind.equals("VP8L")&&(b[20]&255)==47){width=1+(((b[21]&255)|((b[22]&255)<<8))&16383);height=1+((((b[22]&255)>>6)|((b[23]&255)<<2)|((b[24]&255)<<10))&16383);}
                else if(kind.equals("VP8 ")&&(b[23]&255)==157&&b[24]==1&&b[25]==42){width=u16(b,26,true)&16383;height=u16(b,28,true)&16383;}
            }else if(type.equals("audio/wav"))Fault.require(b.length>=44&&ascii(b,0,4).equals("RIFF")&&ascii(b,8,4).equals("WAVE"),"INVALID_MOD_ASSET");
            else if(type.equals("audio/ogg"))Fault.require(ascii(b,0,4).equals("OggS"),"INVALID_MOD_ASSET");
            else Fault.require(ascii(b,0,3).equals("ID3")||(b.length>=2&&(b[0]&255)==255&&(b[1]&224)==224),"INVALID_MOD_ASSET");
            if(type.startsWith("image/"))Fault.require(width>0&&height>0&&width<=2048&&height<=2048,"INVALID_MOD_ASSET");return value;
        }catch(Exception e){throw new Fault("INVALID_MOD_ASSET");}
    }
    private String mediaRef(Object value,String kind,JSONObject assets){if(value==null||value==JSONObject.NULL)return null;String id=id(value);Fault.require(assets.opt(id) instanceof String&&((String)assets.opt(id)).startsWith("data:"+kind+"/"),"INVALID_MOD_ASSET");return id;}
    private JSONArray appearances(JSONObject source,String kind,JSONObject assets){JSONArray raw=list(source.opt(kind),20),out=new JSONArray();Set<String> ids=new HashSet<>();for(int i=0;i<raw.length();i++){JSONObject v=object(raw.opt(i));String id=id(v.opt("id"));Fault.require(ids.add(id),"MOD_CONFLICT");JSONObject clean=SaveCodec.record("id",id,"name",text(v.opt("name"),48,false));String image=mediaRef(v.opt("image"),"image",assets);if(kind.equals("tabletops")){SaveCodec.put(clean,"color",color(v.opt("color"),"#f4efe6"));SaveCodec.put(clean,"gridColor",color(v.opt("gridColor"),"#26363a22"));}else{SaveCodec.put(clean,"face",color(v.opt("face"),"#f4efe6"));SaveCodec.put(clean,"ink",color(v.opt("ink"),"#23303a"));SaveCodec.put(clean,"border",color(v.opt("border"),"#23303a"));SaveCodec.put(clean,"accent",color(v.opt("accent"),"#c79a3e"));}if(image!=null)SaveCodec.put(clean,"image",image);out.put(clean);}return out;}
    JSONObject validatePackage(Object raw){
        if(raw instanceof String){Fault.require(bytes((String)raw)<=MAX_PACKAGE,"MOD_TOO_LARGE");try{raw=SaveCodec.parse((String)raw,MAX_PACKAGE);}catch(Exception e){throw new Fault("INVALID_MOD");}}
        JSONObject source=object(raw);Fault.require(Integer.valueOf(1).equals(source.opt("modFormat"))&&bytes(source.toString())<=MAX_PACKAGE,"INVALID_MOD");JSONObject assets=new JSONObject();Object rawAssets=source.opt("assets");if(rawAssets!=null&&rawAssets!=JSONObject.NULL){Fault.require(rawAssets instanceof JSONObject,"INVALID_MOD_ASSET");JSONObject values=(JSONObject)rawAssets;Fault.require(values.length()<=32,"INVALID_MOD_ASSET");Iterator<String> names=values.keys();while(names.hasNext()){String key=names.next();SaveCodec.put(assets,id(key),asset(values.opt(key)));}}
        JSONArray cards=new JSONArray(),definitions=SaveCodec.arr(codec.catalog.opt("bases"),5);Map<String,JSONObject> byName=new HashMap<>();Set<String> baseNames=new HashSet<>();for(int i=0;i<definitions.length();i++){JSONObject card=SaveCodec.obj(definitions.opt(i));String name=SaveCodec.normalizedName(SaveCodec.str(card.opt("name")));byName.put(name,card);baseNames.add(name);}
        JSONArray rawCards=list(source.opt("cards"),200);Set<String> names=new HashSet<>();for(int i=0;i<rawCards.length();i++){JSONObject card=codec.card(rawCards.opt(i));String name=SaveCodec.normalizedName(SaveCodec.str(card.opt("name")));Fault.require(names.add(name)&&!baseNames.contains(name),"MOD_CONFLICT");cards.put(card);byName.put(name,card);}
        JSONArray starting=new JSONArray(),rawStart=list(source.opt("startingCards"),50);names.clear();for(int i=0;i<rawStart.length();i++){String name=text(rawStart.opt(i),32,false),norm=SaveCodec.normalizedName(name);Fault.require(names.add(norm),"MOD_CONFLICT");Fault.require(byName.containsKey(norm),"MOD_CARD_MISSING");starting.put(name);}
        JSONArray recipes=new JSONArray(),rawRecipes=list(source.opt("recipes"),1000);Set<String> keys=new HashSet<>();for(int i=0;i<rawRecipes.length();i++){JSONObject recipe=object(rawRecipes.opt(i));JSONArray ids=new JSONArray(),ingredients=list(recipe.opt("ingredients"),4);Fault.require(ingredients.length()>=2,"INVALID_MOD");for(int j=0;j<ingredients.length();j++)ids.put(text(ingredients.opt(j),32,false));String result=text(recipe.opt("result"),32,false);Fault.require(byName.containsKey(SaveCodec.normalizedName(result)),"MOD_CARD_MISSING");Fault.require(keys.add(recipeNameKey(ids)),"MOD_CONFLICT");recipes.put(SaveCodec.record("ingredients",ids,"result",result));}
        JSONObject sounds=new JSONObject();Object rawSounds=source.opt("sounds");if(rawSounds!=null&&rawSounds!=JSONObject.NULL)Fault.require(rawSounds instanceof JSONObject,"INVALID_MOD");JSONObject soundSource=rawSounds instanceof JSONObject?(JSONObject)rawSounds:new JSONObject();for(String kind:new String[]{"lift","think","discovery","repeat","failure"}){String ref=mediaRef(soundSource.opt(kind),"audio",assets);if(ref!=null)SaveCodec.put(sounds,kind,ref);}
        Object scriptRaw=or(source.opt("script"),"");Fault.require(scriptRaw instanceof String&&bytes((String)scriptRaw)<=MAX_SCRIPT&&!((String)scriptRaw).contains("\u0000"),"INVALID_MOD_SCRIPT");String script=(String)scriptRaw;
        JSONArray actions=new JSONArray(),rawActions=list(source.opt("actions"),12);Set<String> actionIds=new HashSet<>();for(int i=0;i<rawActions.length();i++){JSONObject action=object(rawActions.opt(i));String id=id(action.opt("id"));Fault.require(actionIds.add(id),"MOD_CONFLICT");actions.put(SaveCodec.record("id",id,"name",text(action.opt("name"),32,false),"description",text(or(action.opt("description"),""),200,true)));}Fault.require(actions.length()==0||!script.trim().isEmpty(),"INVALID_MOD_SCRIPT");
        return SaveCodec.record("modFormat",1,"id",id(source.opt("id")),"name",text(source.opt("name"),48,false),"version",text(source.opt("version"),32,false),"description",text(or(source.opt("description"),""),400,true),"theme",text(or(source.opt("theme"),""),1200,true),"cards",cards,"startingCards",starting,"recipes",recipes,"tabletops",appearances(source,"tabletops",assets),"skins",appearances(source,"skins",assets),"cardBacks",appearances(source,"cardBacks",assets),"sounds",sounds,"assets",assets,"script",script,"actions",actions);
    }
    static String recipeNameKey(JSONArray ingredients){List<String> names=new ArrayList<>();for(int i=0;i<ingredients.length();i++)names.add(SaveCodec.normalizedName(SaveCodec.str(ingredients.opt(i))));Collections.sort(names);return new JSONArray(names).toString();}
    JSONObject state(Object raw){Fault.require(raw instanceof JSONObject&&bytes(raw.toString())<=MAX_STATE,"INVALID_MOD_STATE");return (JSONObject)cleanState(raw,0);}
    private Object cleanState(Object raw,int depth){Fault.require(depth<=20,"INVALID_MOD_STATE");if(raw==null||raw==JSONObject.NULL||raw instanceof String||raw instanceof Boolean)return raw==null?JSONObject.NULL:raw;if(raw instanceof Number){Fault.require(Double.isFinite(((Number)raw).doubleValue()),"INVALID_MOD_STATE");return raw;}if(raw instanceof JSONArray){JSONArray source=(JSONArray)raw,out=new JSONArray();Fault.require(source.length()<=1000,"INVALID_MOD_STATE");for(int i=0;i<source.length();i++)out.put(cleanState(source.opt(i),depth+1));return out;}Fault.require(raw instanceof JSONObject,"INVALID_MOD_STATE");JSONObject source=(JSONObject)raw,out=new JSONObject();Iterator<String> keys=source.keys();while(keys.hasNext()){String key=keys.next();Fault.require(key.length()<=100&&!Arrays.asList("__proto__","constructor","prototype").contains(key),"INVALID_MOD_STATE");SaveCodec.put(out,key,cleanState(source.opt(key),depth+1));}return out;}
    JSONArray mods(Object raw){JSONArray source=list(raw,MAX_MODS),out=new JSONArray();Set<String> ids=new HashSet<>(),recipeKeys=new HashSet<>();for(int i=0;i<source.length();i++){JSONObject item=object(source.opt(i));Fault.require(item.opt("enabled") instanceof Boolean,"INVALID_MOD");JSONObject manifest=validatePackage(item.opt("manifest"));Fault.require(ids.add(SaveCodec.str(manifest.opt("id"))),"MOD_CONFLICT");boolean enabled=(Boolean)item.opt("enabled");if(enabled){JSONArray recipes=list(manifest.opt("recipes"),1000);for(int j=0;j<recipes.length();j++)Fault.require(recipeKeys.add(recipeNameKey(list(object(recipes.opt(j)).opt("ingredients"),4))),"MOD_RECIPE_CONFLICT");}out.put(SaveCodec.record("manifest",manifest,"enabled",enabled,"state",state(or(item.opt("state"),new JSONObject()))));}return out;}
    static JSONObject findEnabled(JSONArray mods,String id){for(int i=0;i<mods.length();i++){JSONObject item=object(mods.opt(i));if(Boolean.TRUE.equals(item.opt("enabled"))&&id.equals(object(item.opt("manifest")).opt("id")))return item;}return null;}
    JSONArray states(Object raw,JSONArray mods){JSONArray source=list(raw,MAX_MODS),out=new JSONArray();Set<String> ids=new HashSet<>();for(int i=0;i<source.length();i++){JSONObject item=object(source.opt(i));String id=id(item.opt("id"));Fault.require(findEnabled(mods,id)!=null,"INVALID_MOD_STATE");Fault.require(ids.add(id),"MOD_CONFLICT");out.put(SaveCodec.record("id",id,"state",state(item.opt("state"))));}return out;}
    JSONObject source(Object raw,JSONArray mods){if(raw==null)raw=SaveCodec.record("kind","unknown");Fault.require(raw instanceof JSONObject,"INVALID_SOURCE");JSONObject value=(JSONObject)raw;Object kind=value.opt("kind");Fault.require(Arrays.asList("ai","recipe","mod","unknown").contains(kind),"INVALID_SOURCE");if(!"mod".equals(kind))return SaveCodec.record("kind",kind);String id=id(value.opt("modId")),name=text(value.opt("modName"),48,false);if(mods!=null)Fault.require(findEnabled(mods,id)!=null,"INVALID_SOURCE");return SaveCodec.record("kind","mod","modId",id,"modName",name);}
    JSONObject findRecipe(JSONObject save,JSONArray ingredientIds){JSONArray cards=SaveCodec.arr(save.opt("cards"),25000),names=new JSONArray();Map<String,String> byId=new HashMap<>();for(int i=0;i<cards.length();i++){JSONObject card=SaveCodec.obj(cards.opt(i));byId.put(SaveCodec.str(card.opt("id")),SaveCodec.str(card.opt("name")));}for(int i=0;i<ingredientIds.length();i++){String name=byId.get(ingredientIds.opt(i));if(name==null)return null;names.put(name);}String key=recipeNameKey(names);JSONArray installed=mods(save.opt("mods"));for(int i=0;i<installed.length();i++){JSONObject item=object(installed.opt(i));if(!Boolean.TRUE.equals(item.opt("enabled")))continue;JSONObject manifest=object(item.opt("manifest"));JSONArray recipes=list(manifest.opt("recipes"),1000);for(int j=0;j<recipes.length();j++){JSONObject recipe=object(recipes.opt(j));if(!key.equals(recipeNameKey(list(recipe.opt("ingredients"),4))))continue;String result=SaveCodec.normalizedName(SaveCodec.str(recipe.opt("result")));JSONArray definitions=new JSONArray();JSONArray base=SaveCodec.arr(codec.catalog.opt("bases"),5);for(int n=0;n<base.length();n++)definitions.put(base.opt(n));JSONArray extra=list(manifest.opt("cards"),200);for(int n=0;n<extra.length();n++)definitions.put(extra.opt(n));for(int n=0;n<definitions.length();n++){JSONObject card=object(definitions.opt(n));if(result.equals(SaveCodec.normalizedName(SaveCodec.str(card.opt("name")))))return SaveCodec.record("result",codec.card(card),"source",SaveCodec.record("kind","mod","modId",manifest.opt("id"),"modName",manifest.opt("name")));}}}return null;}
}
